package com.codex.steward;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CodexBankStewardPluginRunner
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CodexBankStewardPlugin.class);
		RuneLite.main(args);
	}
}

package com.codex.steward;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(CodexBankStewardConfig.GROUP)
public interface CodexBankStewardConfig extends Config
{
	String GROUP = "codexbanksteward";

	@Range(min = 14, max = 730)
	@Units(" days")
	@ConfigItem(
		keyName = "dustDays",
		name = "Dust after",
		description = "An item untouched in your bank for this long is listed as gathering dust",
		position = 0
	)
	default int dustDays()
	{
		return 90;
	}

	@Range(min = 0, max = 90)
	@Units(" days")
	@ConfigItem(
		keyName = "graceDays",
		name = "Recent use grace",
		description = "An item whose quests are done is not listed while it has moved within this many days, since you are still using it",
		position = 1
	)
	default int graceDays()
	{
		return 14;
	}

	@ConfigItem(
		keyName = "bankMarks",
		name = "Mark items in the bank",
		description = "Mark the Steward's list on the items in your bank: a gold diamond for done with, a ring for dusty",
		position = 2
	)
	default boolean bankMarks()
	{
		return true;
	}

	@ConfigItem(
		keyName = "bankSummary",
		name = "Summary at the bank",
		description = "The first time you open your bank each login, write in the chat box what the Steward's list could free",
		position = 3
	)
	default boolean bankSummary()
	{
		return true;
	}
}

package com.codex.steward;

import com.codex.steward.core.Advice;
import com.codex.steward.core.Catalog;
import com.codex.steward.core.Memory;
import com.codex.steward.core.Reckoning;
import com.codex.steward.core.Task;
import com.codex.steward.overlay.BankMarks;
import com.codex.steward.ui.Format;
import com.codex.steward.ui.ItemIcons;
import com.codex.steward.ui.Sigil;
import com.codex.steward.ui.StewardPanel;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.inject.Provides;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.AsyncBufferedImage;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Codex Bank Steward",
	description = "What in your bank is safe to sell or drop: items whose quests and diaries are done, and items untouched for months, with the gold and slots they free",
	tags = {"bank", "clean", "sell", "drop", "quest items", "diary", "space", "slots", "codex"}
)
public class CodexBankStewardPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(CodexBankStewardPlugin.class);
	private static final String MEMORY_KEY = "memory";
	private static final String DATA = "steward-data.json";
	/** Ticks between reading quest and diary progress while varbits are changing. */
	private static final int PROGRESS_TICKS = 10;
	/** Ticks between saves while something has changed. */
	private static final int SAVE_TICKS = 50;
	/** Ticks between fresh reckonings, so prices and the day stay current. */
	private static final int REFRESH_TICKS = 500;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private Gson gson;

	@Inject
	private CodexBankStewardConfig config;

	private final BankMarks marks = new BankMarks();
	private final Map<Integer, String> names = new HashMap<>();
	private final Map<Integer, Boolean> tradeable = new HashMap<>();
	private final Map<String, Quest> quests = new HashMap<>();

	private Catalog catalog;
	private StewardPanel panel;
	private NavigationButton navButton;

	private String profile;
	private Memory memory;
	private Reckoning reckoning;
	private Set<Integer> held = Collections.emptySet();
	private boolean[] done = new boolean[0];
	private boolean progressDirty;
	private boolean reckonDirty;
	private boolean unsaved;
	private boolean summaryDue;
	private int ticks;
	private int lastProgressRead = -PROGRESS_TICKS;

	@Provides
	CodexBankStewardConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexBankStewardConfig.class);
	}

	@Override
	protected void startUp()
	{
		catalog = loadCatalog();
		for (Quest quest : Quest.values())
		{
			quests.put(quest.name(), quest);
		}
		done = new boolean[catalog.getTasks().size()];
		ItemIcons icons = (itemId, onLoaded) ->
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			image.onLoaded(onLoaded);
			return image;
		};
		panel = new StewardPanel(icons, (itemId, kept) -> clientThread.invokeLater(() -> keep(itemId, kept)));
		navButton = NavigationButton.builder()
			.tooltip("Codex Bank Steward")
			.icon(Sigil.icon(16))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		marks.setEnabled(config.bankMarks());
		overlayManager.add(marks);
		clientThread.invokeLater(() ->
		{
			loadProfile();
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				progressDirty = true;
				observeHeld();
				ItemContainer bank = client.getItemContainer(InventoryID.BANK);
				if (bank != null && memory != null)
				{
					unsaved |= memory.observeBank(contents(bank), today());
				}
			}
			reckonDirty = true;
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(marks);
		clientToolbar.removeNavigation(navButton);
		clientThread.invokeLater(() ->
		{
			save();
			memory = null;
			profile = null;
			reckoning = null;
			names.clear();
			tradeable.clear();
		});
		panel = null;
	}

	/** The bundled list of which quests and diaries need which items. */
	private Catalog loadCatalog()
	{
		try (InputStream in = CodexBankStewardPlugin.class.getResourceAsStream(DATA))
		{
			if (in == null)
			{
				throw new IOException("missing " + DATA);
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				return new Catalog(gson.fromJson(reader, Catalog.Data.class));
			}
		}
		catch (IOException | JsonParseException e)
		{
			log.warn("Could not read the Steward's quest and diary data", e);
			return new Catalog(new Catalog.Data());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			progressDirty = true;
			reckonDirty = true;
		}
		else if (state == GameState.LOGIN_SCREEN)
		{
			save();
			summaryDue = false;
			reckonDirty = true;
			publish();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		save();
		loadProfile();
		done = new boolean[catalog.getTasks().size()];
		progressDirty = true;
		reckonDirty = true;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CodexBankStewardConfig.GROUP.equals(event.getGroup()))
		{
			marks.setEnabled(config.bankMarks());
			reckonDirty = true;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		progressDirty = true;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (client.getGameState() != GameState.LOGGED_IN || memory == null)
		{
			return;
		}
		int id = event.getContainerId();
		if (id == InventoryID.BANK)
		{
			if (!memory.hasSeenBank() || reckoning == null)
			{
				summaryDue = true;
			}
			unsaved |= memory.observeBank(contents(event.getItemContainer()), today());
			reckonDirty = true;
		}
		else if (id == InventoryID.INV || id == InventoryID.WORN)
		{
			observeHeld();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (memory == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		ticks++;
		if (progressDirty && ticks - lastProgressRead >= PROGRESS_TICKS)
		{
			progressDirty = false;
			lastProgressRead = ticks;
			reckonDirty |= readProgress();
		}
		if (reckonDirty || ticks % REFRESH_TICKS == 0)
		{
			reckon();
			publish();
			if (summaryDue && reckoning != null)
			{
				summaryDue = false;
				summary();
			}
		}
		if (unsaved && ticks % SAVE_TICKS == 0)
		{
			save();
		}
	}

	private void keep(int itemId, boolean kept)
	{
		if (memory == null)
		{
			return;
		}
		memory.setKept(itemId, kept);
		unsaved = true;
		reckonDirty = true;
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			reckon();
			publish();
		}
	}

	/** Reads which quests and diaries are done; returns true when anything changed. */
	private boolean readProgress()
	{
		List<Task> tasks = catalog.getTasks();
		boolean changed = false;
		for (int i = 0; i < tasks.size(); i++)
		{
			Task task = tasks.get(i);
			boolean finished;
			if (task.isDiary())
			{
				finished = client.getVarbitValue(task.getVarbit()) >= task.getValue();
			}
			else
			{
				Quest quest = quests.get(task.getQuest());
				finished = quest != null && quest.getState(client) == QuestState.FINISHED;
			}
			if (done[i] != finished)
			{
				done[i] = finished;
				changed = true;
			}
		}
		return changed;
	}

	private void observeHeld()
	{
		Set<Integer> now = new HashSet<>();
		for (int id : new int[]{InventoryID.INV, InventoryID.WORN})
		{
			now.addAll(contents(client.getItemContainer(id)).keySet());
		}
		held = now;
		if (memory != null)
		{
			unsaved |= memory.observeHeld(now, today());
		}
		reckonDirty = true;
	}

	private Map<Integer, Long> contents(ItemContainer container)
	{
		Map<Integer, Long> items = new HashMap<>();
		if (container == null)
		{
			return items;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() < 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			items.merge(itemManager.canonicalize(item.getId()), (long) item.getQuantity(), Long::sum);
		}
		return items;
	}

	private static long today()
	{
		return LocalDate.now().toEpochDay();
	}

	private void reckon()
	{
		reckonDirty = false;
		if (memory == null || !memory.hasSeenBank())
		{
			reckoning = null;
			return;
		}
		Map<Integer, Long> bank = memory.getBank();
		for (int id : bank.keySet())
		{
			describe(id);
		}
		Reckoning.Rules rules = new Reckoning.Rules(config.dustDays(), config.graceDays());
		reckoning = Reckoning.of(catalog, memory, bank, held, done, itemManager::getItemPrice,
			id -> tradeable.getOrDefault(id, false), rules, today());
	}

	private void describe(int itemId)
	{
		if (!names.containsKey(itemId))
		{
			ItemComposition item = itemManager.getItemComposition(itemId);
			names.put(itemId, item.getName());
			tradeable.put(itemId, item.isTradeable());
		}
	}

	private void loadProfile()
	{
		profile = configManager.getRSProfileKey();
		memory = null;
		reckoning = null;
		if (profile == null)
		{
			return;
		}
		try
		{
			String saved = configManager.getRSProfileConfiguration(CodexBankStewardConfig.GROUP, MEMORY_KEY);
			if (saved != null && !saved.isEmpty())
			{
				Memory read = gson.fromJson(saved, Memory.class);
				memory = read == null ? null : read.repair();
			}
		}
		catch (JsonParseException e)
		{
			log.warn("Could not read the Steward's saved memory, starting afresh", e);
		}
		if (memory == null)
		{
			memory = new Memory();
		}
		unsaved = false;
		reckonDirty = true;
	}

	private void save()
	{
		if (profile == null || memory == null || !unsaved)
		{
			return;
		}
		unsaved = false;
		configManager.setConfiguration(CodexBankStewardConfig.GROUP, profile, MEMORY_KEY, gson.toJson(memory));
	}

	private void summary()
	{
		if (!config.bankSummary() || reckoning.freedSlots() == 0)
		{
			return;
		}
		int spent = reckoning.getSpent().size();
		int dust = reckoning.getDust().size();
		StringBuilder what = new StringBuilder();
		if (spent > 0)
		{
			what.append(spent).append(spent == 1 ? " item is" : " items are").append(" done with");
		}
		if (dust > 0)
		{
			what.append(spent > 0 ? " and " : "").append(dust).append(dust == 1 ? " is" : " are").append(" gathering dust");
		}
		ChatMessageBuilder line = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append("Codex Bank Steward: ")
			.append(ChatColorType.NORMAL).append(what + ". Clearing them frees ")
			.append(ChatColorType.HIGHLIGHT).append(reckoning.freedSlots() + (reckoning.freedSlots() == 1 ? " slot" : " slots"))
			.append(ChatColorType.NORMAL).append(" and ")
			.append(ChatColorType.HIGHLIGHT).append(Format.coins(reckoning.freedValue()) + " gp")
			.append(ChatColorType.NORMAL).append(".");
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(line.build())
			.build());
	}

	/** Hands the panel and the bank marks the latest reckoning; it is immutable, so Swing may keep it. */
	private void publish()
	{
		StewardPanel target = panel;
		Reckoning shown = reckoning;
		Map<Integer, Advice.Verdict> marked = new HashMap<>();
		if (shown != null)
		{
			for (Advice a : shown.getSpent())
			{
				marked.put(a.getItemId(), Advice.Verdict.SPENT);
			}
			for (Advice a : shown.getDust())
			{
				marked.put(a.getItemId(), Advice.Verdict.DUST);
			}
		}
		marks.setMarks(marked);
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		Player player = client.getLocalPlayer();
		String name = loggedIn && player != null ? player.getName() : null;
		StewardPanel.State state = !loggedIn ? StewardPanel.State.LOGGED_OUT
			: shown == null ? StewardPanel.State.WAITING_FOR_BANK : StewardPanel.State.READY;
		Map<Integer, String> shownNames = new HashMap<>(names);
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.update(shown, shownNames, name, state));
		}
	}
}

package com.codex.steward.core;

import java.util.Collections;
import java.util.List;

/** One item in the bank and what the Steward makes of it. */
public final class Advice
{
	/** Why an item is on the list. */
	public enum Verdict
	{
		/** Every quest and diary that needs it is done. */
		SPENT,
		/** Untouched for longer than the player's dust threshold. */
		DUST,
		/** Still needed by a quest or diary that is not done. */
		NEEDED,
		/** The player chose to keep it. */
		KEPT
	}

	private final int itemId;
	private final long quantity;
	private final long price;
	private final boolean tradeable;
	private final Verdict verdict;
	private final List<String> tasks;
	private final long untouchedDays;

	public Advice(int itemId, long quantity, long price, boolean tradeable, Verdict verdict, List<String> tasks, long untouchedDays)
	{
		this.itemId = itemId;
		this.quantity = quantity;
		this.price = price;
		this.tradeable = tradeable;
		this.verdict = verdict;
		this.tasks = tasks == null ? Collections.emptyList() : Collections.unmodifiableList(tasks);
		this.untouchedDays = untouchedDays;
	}

	public int getItemId()
	{
		return itemId;
	}

	public long getQuantity()
	{
		return quantity;
	}

	/** The Grand Exchange price of one, or 0 when it cannot be traded. */
	public long getPrice()
	{
		return price;
	}

	/** What selling the whole stack would bring. */
	public long getValue()
	{
		return tradeable ? price * quantity : 0;
	}

	public boolean isTradeable()
	{
		return tradeable;
	}

	public Verdict getVerdict()
	{
		return verdict;
	}

	/** For SPENT, the finished tasks it served; for NEEDED, the unfinished tasks that want it. */
	public List<String> getTasks()
	{
		return tasks;
	}

	public long getUntouchedDays()
	{
		return untouchedDays;
	}
}

package com.codex.steward.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Which quests and diaries need which items, from the bundled steward-data.json.
 *
 * <p>Each need is one requirement of one task: a quantity and the items that satisfy it, best
 * first. A need with several items is an "any of" choice, met by keeping one of them.</p>
 */
public final class Catalog
{
	/** The file as stored; Gson fills it in. */
	public static final class Data
	{
		String source;
		List<Task> tasks;
		List<int[]> needs;
		int[] general;
		int[] lasting;
	}

	/** One requirement: a task, a quantity and the items that meet it. */
	public static final class Need
	{
		private final int task;
		private final int quantity;
		private final int[] items;

		Need(int task, int quantity, int[] items)
		{
			this.task = task;
			this.quantity = quantity;
			this.items = items;
		}

		public int getTask()
		{
			return task;
		}

		public int getQuantity()
		{
			return quantity;
		}

		public int[] getItems()
		{
			return items;
		}
	}

	private final List<Task> tasks;
	private final List<Need> needs = new ArrayList<>();
	private final Map<Integer, List<Need>> byItem = new HashMap<>();
	private final Set<Integer> general = new HashSet<>();
	private final Set<Integer> lasting = new HashSet<>();

	public Catalog(Data data)
	{
		tasks = data.tasks == null ? Collections.emptyList() : Collections.unmodifiableList(new ArrayList<>(data.tasks));
		if (data.needs != null)
		{
			for (int[] raw : data.needs)
			{
				if (raw.length < 3 || raw[0] < 0 || raw[0] >= tasks.size())
				{
					continue;
				}
				int[] items = new int[raw.length - 2];
				System.arraycopy(raw, 2, items, 0, items.length);
				Need need = new Need(raw[0], Math.max(1, raw[1]), items);
				needs.add(need);
				for (int item : items)
				{
					byItem.computeIfAbsent(item, k -> new ArrayList<>()).add(need);
				}
			}
		}
		if (data.general != null)
		{
			for (int id : data.general)
			{
				general.add(id);
			}
		}
		if (data.lasting != null)
		{
			for (int id : data.lasting)
			{
				lasting.add(id);
			}
		}
	}

	public List<Task> getTasks()
	{
		return tasks;
	}

	public List<Need> getNeeds()
	{
		return Collections.unmodifiableList(needs);
	}

	/** Every need the item can meet, empty when no quest or diary names it. */
	public List<Need> needsOf(int itemId)
	{
		List<Need> list = byItem.get(itemId);
		return list == null ? Collections.emptyList() : list;
	}

	/** A tool, rune, food or other good that stays useful whatever is done. */
	public boolean isGeneral(int itemId)
	{
		return general.contains(itemId);
	}

	/** A reward or access item with a use long after the task that names it. */
	public boolean isLasting(int itemId)
	{
		return lasting.contains(itemId);
	}
}

package com.codex.steward.core;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * What the Steward remembers about one account: the bank as last seen, the day each item last
 * moved, the day it began watching and the items the player chose to keep. Saved per profile.
 *
 * <p>An item has moved when its count in the bank changes, or whenever it is carried or worn.
 * Items already in the bank on the first day have no move of their own; they count as
 * untouched since the Steward began watching.</p>
 */
public final class Memory
{
	/** The epoch day watching began, or -1 before the bank has been seen. */
	private long since = -1;
	private Map<Integer, Long> bank = new HashMap<>();
	private Map<Integer, Long> moved = new HashMap<>();
	private Set<Integer> keep = new HashSet<>();

	/** Fills in anything a saved copy from an older version lacks. */
	public Memory repair()
	{
		if (bank == null)
		{
			bank = new HashMap<>();
		}
		if (moved == null)
		{
			moved = new HashMap<>();
		}
		if (keep == null)
		{
			keep = new HashSet<>();
		}
		return this;
	}

	public boolean hasSeenBank()
	{
		return since >= 0;
	}

	public long getSince()
	{
		return since;
	}

	/** The bank as last seen: item to count. */
	public Map<Integer, Long> getBank()
	{
		return bank;
	}

	/**
	 * Records a look at the bank and marks every item whose count changed since the last look.
	 *
	 * @return true when anything changed
	 */
	public boolean observeBank(Map<Integer, Long> now, long today)
	{
		if (since < 0)
		{
			since = today;
			bank = new HashMap<>(now);
			return true;
		}
		boolean changed = false;
		for (Map.Entry<Integer, Long> e : now.entrySet())
		{
			Long before = bank.get(e.getKey());
			if (before == null || !before.equals(e.getValue()))
			{
				changed |= touch(e.getKey(), today);
			}
		}
		for (Integer id : bank.keySet())
		{
			if (!now.containsKey(id))
			{
				changed |= touch(id, today);
			}
		}
		if (!bank.equals(now))
		{
			bank = new HashMap<>(now);
			changed = true;
		}
		return changed;
	}

	/** Marks items carried or worn as in use today. */
	public boolean observeHeld(Iterable<Integer> items, long today)
	{
		boolean changed = false;
		for (Integer id : items)
		{
			changed |= touch(id, today);
		}
		return changed;
	}

	private boolean touch(int id, long today)
	{
		Long before = moved.put(id, today);
		return before == null || before != today;
	}

	/** The day the item last moved, or -1 if it has not moved while watched. */
	public long lastMoved(int id)
	{
		Long day = moved.get(id);
		return day == null ? -1 : day;
	}

	/** Whole days since the item last moved, counting from the start of watching if it never has. */
	public long untouchedDays(int id, long today)
	{
		long last = lastMoved(id);
		long from = last >= 0 ? last : since;
		return from < 0 ? 0 : Math.max(0, today - from);
	}

	public boolean isKept(int id)
	{
		return keep.contains(id);
	}

	public Set<Integer> getKept()
	{
		return keep;
	}

	public void setKept(int id, boolean kept)
	{
		if (kept)
		{
			keep.add(id);
		}
		else
		{
			keep.remove(id);
		}
	}
}

package com.codex.steward.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntPredicate;
import java.util.function.IntToLongFunction;

/**
 * The Steward's reckoning of a bank: what can go because its quests and diaries are done, what
 * has gathered dust, what is still owed to unfinished work, and what the player chose to keep.
 *
 * <p>An item is spent only when the catalog names it, every task naming it is done, it is not a
 * general good or a lasting reward, the stack is no bigger than leftovers from those tasks, and it
 * has not moved within the grace period. An "any of"
 * need of an unfinished task holds one item: the first of its choices the player owns, so a
 * spare pickaxe is not held back because some quest wants a pickaxe.</p>
 */
public final class Reckoning
{
	/** How the Steward judges; both in days. */
	public static final class Rules
	{
		final int dustDays;
		final int graceDays;

		public Rules(int dustDays, int graceDays)
		{
			this.dustDays = Math.max(1, dustDays);
			this.graceDays = Math.max(0, graceDays);
		}
	}

	private final List<Advice> spent;
	private final List<Advice> dust;
	private final List<Advice> kept;
	private final Map<String, List<Advice>> needed;
	private final long watchedDays;
	private final int dustDays;
	private final int tasksDone;
	private final int tasksTotal;

	private Reckoning(List<Advice> spent, List<Advice> dust, List<Advice> kept, Map<String, List<Advice>> needed,
		long watchedDays, int dustDays, int tasksDone, int tasksTotal)
	{
		this.spent = spent;
		this.dust = dust;
		this.kept = kept;
		this.needed = needed;
		this.watchedDays = watchedDays;
		this.dustDays = dustDays;
		this.tasksDone = tasksDone;
		this.tasksTotal = tasksTotal;
	}

	/**
	 * @param bank item to count, as in the bank now
	 * @param held items carried or worn, which can meet a need in place of the bank's
	 * @param done for each catalog task, whether it is finished
	 * @param price the Grand Exchange price of one
	 * @param tradeable whether an item can be sold
	 */
	public static Reckoning of(Catalog catalog, Memory memory, Map<Integer, Long> bank, Set<Integer> held, boolean[] done,
		IntToLongFunction price, IntPredicate tradeable, Rules rules, long today)
	{
		List<Task> tasks = catalog.getTasks();
		int doneCount = 0;
		for (int i = 0; i < tasks.size() && i < done.length; i++)
		{
			if (done[i])
			{
				doneCount++;
			}
		}

		// Which owned item each unfinished need holds back, and for which tasks.
		Map<Integer, Set<Integer>> holding = new HashMap<>();
		for (Catalog.Need need : catalog.getNeeds())
		{
			if (isDone(done, need.getTask()))
			{
				continue;
			}
			for (int item : need.getItems())
			{
				if (held.contains(item) || bank.getOrDefault(item, 0L) > 0)
				{
					holding.computeIfAbsent(item, k -> new HashSet<>()).add(need.getTask());
					break;
				}
			}
		}

		List<Advice> spent = new ArrayList<>();
		List<Advice> dust = new ArrayList<>();
		List<Advice> kept = new ArrayList<>();
		Map<Integer, List<Advice>> neededByTask = new HashMap<>();
		long watched = memory.hasSeenBank() ? Math.max(0, today - memory.getSince()) : 0;

		for (Map.Entry<Integer, Long> e : bank.entrySet())
		{
			int id = e.getKey();
			long qty = e.getValue();
			if (qty <= 0)
			{
				continue;
			}
			boolean canSell = tradeable.test(id);
			long each = canSell ? Math.max(0, price.applyAsLong(id)) : 0;
			long untouched = memory.untouchedDays(id, today);

			if (memory.isKept(id))
			{
				kept.add(new Advice(id, qty, each, canSell, Advice.Verdict.KEPT, null, untouched));
				continue;
			}
			Set<Integer> wanting = holding.get(id);
			if (wanting != null)
			{
				List<String> names = names(tasks, wanting);
				Advice advice = new Advice(id, qty, each, canSell, Advice.Verdict.NEEDED, names, untouched);
				for (int t : wanting)
				{
					neededByTask.computeIfAbsent(t, k -> new ArrayList<>()).add(advice);
				}
				continue;
			}
			if (isSpent(catalog, memory, id, qty, done, rules, today))
			{
				Set<Integer> served = new HashSet<>();
				for (Catalog.Need need : catalog.needsOf(id))
				{
					served.add(need.getTask());
				}
				spent.add(new Advice(id, qty, each, canSell, Advice.Verdict.SPENT, names(tasks, served), untouched));
				continue;
			}
			if (watched >= rules.dustDays && untouched >= rules.dustDays && !catalog.isLasting(id))
			{
				dust.add(new Advice(id, qty, each, canSell, Advice.Verdict.DUST, null, untouched));
			}
		}

		Comparator<Advice> byValue = Comparator.comparingLong(Advice::getValue).reversed()
			.thenComparing(Comparator.comparingLong(Advice::getUntouchedDays).reversed())
			.thenComparingInt(Advice::getItemId);
		spent.sort(byValue);
		dust.sort(byValue);
		kept.sort(byValue);

		// Unfinished tasks in catalog order, each with what it holds back, most valuable first.
		Map<String, List<Advice>> needed = new LinkedHashMap<>();
		for (int t = 0; t < tasks.size(); t++)
		{
			List<Advice> list = neededByTask.get(t);
			if (list != null)
			{
				list.sort(byValue);
				needed.put(tasks.get(t).getName(), Collections.unmodifiableList(list));
			}
		}
		return new Reckoning(Collections.unmodifiableList(spent), Collections.unmodifiableList(dust),
			Collections.unmodifiableList(kept), Collections.unmodifiableMap(needed), watched, rules.dustDays, doneCount, tasks.size());
	}

	/** The most a bank may hold of an item and still be leftovers from the tasks that wanted it. */
	static long leftoverLimit(int largestNeed)
	{
		return largestNeed * 2L + 3;
	}

	private static boolean isSpent(Catalog catalog, Memory memory, int id, long qty, boolean[] done, Rules rules, long today)
	{
		List<Catalog.Need> needs = catalog.needsOf(id);
		if (needs.isEmpty() || catalog.isGeneral(id) || catalog.isLasting(id))
		{
			return false;
		}
		int largest = 0;
		for (Catalog.Need need : needs)
		{
			if (!isDone(done, need.getTask()))
			{
				return false;
			}
			largest = Math.max(largest, need.getQuantity());
		}
		// A stack far beyond what any quest asked for was gathered for something else, like skilling.
		if (qty > leftoverLimit(largest))
		{
			return false;
		}
		long last = memory.lastMoved(id);
		return last < 0 || today - last >= rules.graceDays;
	}

	private static boolean isDone(boolean[] done, int task)
	{
		return task >= 0 && task < done.length && done[task];
	}

	private static List<String> names(List<Task> tasks, Set<Integer> indexes)
	{
		List<Integer> sorted = new ArrayList<>(indexes);
		Collections.sort(sorted);
		List<String> names = new ArrayList<>();
		for (int i : sorted)
		{
			names.add(tasks.get(i).getName());
		}
		return names;
	}

	public List<Advice> getSpent()
	{
		return spent;
	}

	public List<Advice> getDust()
	{
		return dust;
	}

	public List<Advice> getKept()
	{
		return kept;
	}

	/** Unfinished task name to the bank items it holds back. */
	public Map<String, List<Advice>> getNeeded()
	{
		return needed;
	}

	/** Days since the Steward began watching this bank. */
	public long getWatchedDays()
	{
		return watchedDays;
	}

	public int getDustDays()
	{
		return dustDays;
	}

	public int getTasksDone()
	{
		return tasksDone;
	}

	public int getTasksTotal()
	{
		return tasksTotal;
	}

	/** What selling everything on the list would bring. */
	public long freedValue()
	{
		long total = 0;
		for (Advice a : spent)
		{
			total += a.getValue();
		}
		for (Advice a : dust)
		{
			total += a.getValue();
		}
		return total;
	}

	/** Bank slots the list would free. */
	public int freedSlots()
	{
		return spent.size() + dust.size();
	}
}

package com.codex.steward.core;

/**
 * A quest, miniquest or achievement diary tier that needs items. Quests are read through
 * RuneLite's Quest enum by name; a diary tier is done once its reward varbit reaches its value.
 */
public final class Task
{
	public static final String QUEST = "quest";
	public static final String MINIQUEST = "miniquest";
	public static final String DIARY = "diary";

	private String name;
	private String kind;
	private String quest;
	private int varbit;
	private int value;

	public Task()
	{
	}

	public Task(String name, String kind, String quest, int varbit, int value)
	{
		this.name = name;
		this.kind = kind;
		this.quest = quest;
		this.varbit = varbit;
		this.value = value;
	}

	public String getName()
	{
		return name;
	}

	public String getKind()
	{
		return kind;
	}

	public boolean isDiary()
	{
		return DIARY.equals(kind);
	}

	/** The name of the net.runelite.api.Quest constant, or null for a diary. */
	public String getQuest()
	{
		return quest;
	}

	public int getVarbit()
	{
		return varbit;
	}

	public int getValue()
	{
		return value;
	}

	/** "Quest", "Miniquest" or "Diary", for the panel. */
	public String kindLabel()
	{
		return isDiary() ? "Diary" : MINIQUEST.equals(kind) ? "Miniquest" : "Quest";
	}
}

package com.codex.steward.overlay;

import com.codex.steward.core.Advice;
import com.codex.steward.ui.Theme;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.util.Collections;
import java.util.Map;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Marks the Steward's list in the bank itself: a gilt diamond on items whose work is done and a
 * ring of ash on items gathering dust, each with a faint rim round the slot, so the list can be
 * cleared straight from the bank without looking back at the panel.
 */
public class BankMarks extends WidgetItemOverlay
{
	private volatile Map<Integer, Advice.Verdict> marks = Collections.emptyMap();
	private volatile boolean enabled = true;

	public BankMarks()
	{
		showOnBank();
	}

	public void setMarks(Map<Integer, Advice.Verdict> marks)
	{
		this.marks = marks;
	}

	public void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem item)
	{
		if (!enabled)
		{
			return;
		}
		Advice.Verdict verdict = marks.get(itemId);
		if (verdict == null)
		{
			return;
		}
		Rectangle r = item.getCanvasBounds();
		Theme.smooth(g);
		Color color = Theme.verdict(verdict);
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(color, 70));
		g.draw(new RoundRectangle2D.Float(r.x + 0.5f, r.y + 0.5f, r.width - 1, r.height - 1, 6, 6));

		float cx = r.x + r.width - 5.5f;
		float cy = r.y + r.height - 5.5f;
		if (verdict == Advice.Verdict.SPENT)
		{
			Path2D diamond = new Path2D.Float();
			diamond.moveTo(cx, cy - 4.5f);
			diamond.lineTo(cx + 4.5f, cy);
			diamond.lineTo(cx, cy + 4.5f);
			diamond.lineTo(cx - 4.5f, cy);
			diamond.closePath();
			g.setColor(Theme.INK_DEEP);
			g.setStroke(new BasicStroke(2f));
			g.draw(diamond);
			g.setColor(Theme.GOLD_BRIGHT);
			g.fill(diamond);
		}
		else
		{
			Ellipse2D ring = new Ellipse2D.Float(cx - 3.5f, cy - 3.5f, 7, 7);
			g.setColor(Theme.INK_DEEP);
			g.setStroke(new BasicStroke(3f));
			g.draw(ring);
			g.setColor(color);
			g.setStroke(new BasicStroke(1.4f));
			g.draw(ring);
		}
	}
}

package com.codex.steward.ui;

import com.codex.steward.core.Advice;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;

/**
 * One item from the bank: the item in a dark well like a bank slot with its count in the game's
 * own colours, its name and the Steward's reason under it, and on the right what it would sell
 * for. A thin bar down the left edge carries the verdict's colour. Clicking offers to keep the
 * item off the list, or to let it back on.
 */
class AdviceRow extends JComponent
{
	private static final int WELL = 32;

	private final Advice advice;
	private final String name;
	private final String note;
	private final ItemIcons icons;
	private boolean hover;

	/**
	 * @param action label for the click menu, or null for a row with no action
	 * @param onAction run when the menu item is chosen
	 */
	AdviceRow(Advice advice, String name, String note, ItemIcons icons, String action, Runnable onAction)
	{
		this.advice = advice;
		this.name = name;
		this.note = note;
		this.icons = icons;
		setOpaque(false);
		setPreferredSize(new Dimension(10, WELL + 6));
		setToolTipText(tooltip());
		if (action != null)
		{
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			JPopupMenu menu = new JPopupMenu();
			JMenuItem item = new JMenuItem(action);
			item.addActionListener(e -> onAction.run());
			menu.add(item);
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseEntered(MouseEvent e)
				{
					hover = true;
					repaint();
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					hover = false;
					repaint();
				}

				@Override
				public void mouseReleased(MouseEvent e)
				{
					if (contains(e.getPoint()))
					{
						menu.show(AdviceRow.this, e.getX(), e.getY());
					}
				}
			});
		}
	}

	private String tooltip()
	{
		StringBuilder tip = new StringBuilder("<html>").append(Ui.escape(name));
		if (advice.getQuantity() > 1)
		{
			tip.append(" x ").append(Format.quantity(advice.getQuantity()));
		}
		if (advice.isTradeable() && advice.getPrice() > 0)
		{
			tip.append("<br>").append(Format.coins(advice.getPrice())).append(" gp each");
		}
		else if (!advice.isTradeable())
		{
			tip.append("<br>Cannot be traded");
		}
		for (String task : advice.getTasks())
		{
			tip.append("<br>").append(advice.getVerdict() == Advice.Verdict.NEEDED ? "For " : "Done: ").append(Ui.escape(task));
		}
		return tip.append("</html>").toString();
	}

	/** What the right of the row says: the sale value, or how the slot is freed when it cannot be sold. */
	private String amount()
	{
		if (!advice.isTradeable())
		{
			return advice.getVerdict() == Advice.Verdict.SPENT || advice.getVerdict() == Advice.Verdict.DUST ? "Drop" : "-";
		}
		return Format.coins(advice.getValue());
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		Color accent = Theme.verdict(advice.getVerdict());

		if (hover)
		{
			g.setColor(Theme.alpha(Theme.GOLD, 18));
			g.fill(new RoundRectangle2D.Float(0, 0, w, h, 8, 8));
		}

		int y = 3;
		g.setPaint(new GradientPaint(0, y, accent, 0, y + WELL, Theme.alpha(accent, 60)));
		g.fillRect(0, y + 3, 2, WELL - 6);

		int wx = 5;
		RoundRectangle2D well = new RoundRectangle2D.Float(wx + 0.5f, y + 0.5f, WELL + 4, WELL - 1, 7, 7);
		g.setPaint(new GradientPaint(0, y, Theme.INK_DEEP, 0, y + WELL, Theme.mix(Theme.INK_DEEP, Theme.CARD, 0.6)));
		g.fill(well);
		g.setColor(hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT);
		g.draw(well);
		BufferedImage icon = icons == null ? null : icons.icon(advice.getItemId(), this::repaint);
		if (icon != null)
		{
			g.drawImage(icon, wx + 2 + (WELL - icon.getWidth()) / 2, y + (WELL - icon.getHeight()) / 2 + 1, null);
		}
		if (advice.getQuantity() > 1)
		{
			g.setFont(Theme.small());
			Ui.shadowed(g, Format.stack(advice.getQuantity()), wx + 2, y + 10, Format.stackColor(advice.getQuantity()));
		}

		int tx = wx + WELL + 12;
		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		String amount = amount();
		int aw = fm.stringWidth(amount);
		int base = y + fm.getAscent() + 1;
		Color amountColor = !advice.isTradeable() ? Theme.TEXT_FAINT : advice.getVerdict() == Advice.Verdict.NEEDED ? Theme.TEXT_MUTED : Theme.GOLD;
		Ui.shadowed(g, amount, w - aw - 2, base, amountColor);
		Ui.shadowed(g, Ui.clip(name, fm, w - tx - aw - 10), tx, base, Theme.TEXT);

		if (note != null)
		{
			g.setFont(Theme.small());
			FontMetrics small = g.getFontMetrics();
			g.setColor(Theme.mix(Theme.TEXT_FAINT, accent, 0.35));
			g.drawString(Ui.clip(note, small, w - tx - 2), tx, y + WELL - 5);
		}
		g.dispose();
	}
}

package com.codex.steward.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.steward.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.steward.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * The crest at the top of the panel: the Steward's medallion, what clearing out the list would
 * bring in large gilt figures, and how many slots, spent items and dusty items that is.
 */
public class Crest extends JComponent
{
	private static final int HEIGHT = 104;

	private final Animator count = new Animator(this);
	private String player;
	private String status = "Log in to take stock";
	private long total;
	private boolean known;
	private final int[] counts = new int[3];
	private static final String[] COUNTS = {"Slots", "Done", "Dusty"};

	public Crest()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
	}

	/**
	 * @param total what the list would sell for, or null before the bank is known
	 * @param status a line in place of the counts, or null to show them
	 * @param counts slots freed, items done with and dusty items
	 */
	public void update(String player, Long total, String status, int[] counts)
	{
		this.player = player;
		this.status = status;
		this.known = total != null;
		if (total != null)
		{
			boolean animate = this.total != 0 && Math.abs(total - this.total) < Math.max(1, this.total);
			this.total = total;
			count.set(total, animate);
		}
		for (int i = 0; i < 3; i++)
		{
			this.counts[i] = counts == null ? 0 : counts[i];
		}
		repaint();
	}

	/**
	 * Draws text at twice the size of the game's bold font by doubling every pixel, the way the
	 * game itself draws large numbers, so the figures stay crisp instead of being re-rasterised.
	 *
	 * @return the width drawn
	 */
	private static int paintLarge(Graphics2D g, String text, int x, int y)
	{
		Font font = Theme.title();
		FontMetrics fm = g.getFontMetrics(font);
		int w = Math.max(1, fm.stringWidth(text) + 1);
		int h = fm.getHeight() + 1;
		BufferedImage small = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = small.createGraphics();
		sg.setFont(font);
		sg.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		int base = fm.getAscent();
		sg.setColor(Color.BLACK);
		sg.drawString(text, 1, base + 1);
		sg.setPaint(new GradientPaint(0, base - fm.getAscent() + 3, Theme.GOLD_BRIGHT, 0, base, Theme.GOLD));
		sg.drawString(text, 0, base);
		sg.dispose();
		Graphics2D lg = (Graphics2D) g.create();
		lg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		lg.drawImage(small, x, y - 2 * fm.getAscent() + 22, w * 2, h * 2, null);
		lg.dispose();
		return w * 2;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.GOLD_DIM, 0.22), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// The medallion: a gilt ring with the mark inside, lit from above.
		int mx = 10;
		int my = 14;
		int md = 54;
		g.setPaint(new RadialGradientPaint(mx + md / 2f, my + md / 3f, md * 0.7f, new float[]{0, 1},
			new Color[]{Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35), Theme.INK_DEEP}));
		g.fill(new Ellipse2D.Float(mx, my, md, md));
		g.setStroke(new BasicStroke(2f));
		g.setPaint(new GradientPaint(mx, my, Theme.GOLD_BRIGHT, mx, my + md, Theme.GOLD_DIM));
		g.draw(new Ellipse2D.Float(mx + 1, my + 1, md - 2, md - 2));
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 70));
		g.draw(new Ellipse2D.Float(mx + 5, my + 5, md - 10, md - 10));
		Sigil.paint(g, mx + 11, my + 11, md - 22);

		int tx = mx + md + 12;
		int room = w - tx - 8;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		String heading = player != null ? player + "  -  COULD FREE" : "COULD FREE";
		if (small.stringWidth(heading) > room)
		{
			heading = "COULD FREE";
		}
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(heading, small, room), tx, 22);

		String figure = known ? Format.coins(Math.round(count.get())) : "-";
		int top = 27;
		int figureW = paintLarge(g, figure, tx, top);
		if (known)
		{
			g.setFont(Theme.small());
			g.setColor(Theme.GOLD_DIM);
			g.drawString("gp", tx + figureW + 3, top + 18);
		}
		int fy = top + 26;
		int cy = fy + 24;
		g.setFont(Theme.small());
		if (status != null)
		{
			g.setColor(Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.3));
			g.drawString(Ui.clip(status, small, room), tx, cy);
		}
		else
		{
			int cw = room / 3;
			Color[] colors = {Theme.TEXT, Theme.SPENT, Theme.DUST};
			for (int i = 0; i < 3; i++)
			{
				int x = tx + i * cw;
				g.setColor(Theme.TEXT_FAINT);
				g.drawString(COUNTS[i], x, cy - 11);
				Ui.shadowed(g, String.valueOf(counts[i]), x, cy + 1, counts[i] > 0 ? colors[i] : Theme.TEXT_FAINT);
			}
		}

		// The gilt rule under the crest, with a diamond at its middle.
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
	}
}

package com.codex.steward.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/**
 * Shown until the Steward has watched the bank long enough to call anything dusty: how many
 * days it has watched, against the threshold, as an hourglass of ash filling a gilt bar.
 */
class DustWatch extends JComponent
{
	private final long watched;
	private final int needed;

	DustWatch(long watched, int needed)
	{
		this.watched = watched;
		this.needed = needed;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 62));
		setToolTipText("Items count as dust once they sit untouched for " + needed + " days, so the Steward must watch that long first");
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setClip(shape);
		g.setPaint(new GradientPaint(0, 0, Theme.DUST, 0, h, Theme.alpha(Theme.DUST, 90)));
		g.fillRect(0, 0, 3, h);
		g.setClip(null);

		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		Ui.shadowed(g, "Watching for dust", 12, 8 + fm.getAscent(), Theme.DUST);
		String day = "day " + Math.min(watched, needed) + " of " + needed;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(day, w - small.stringWidth(day) - 10, 8 + fm.getAscent());

		int bx = 12;
		int by = 30;
		int bw = w - 22;
		RoundRectangle2D track = new RoundRectangle2D.Float(bx, by, bw, 6, 6, 6);
		g.setColor(Theme.INK_DEEP);
		g.fill(track);
		double share = Math.max(0, Math.min(1, watched / (double) needed));
		float fill = (float) Math.max(4, bw * share);
		g.setPaint(new GradientPaint(bx, 0, Theme.mix(Theme.DUST, Theme.INK, 0.5), bx + bw, 0, Theme.GOLD));
		g.fill(new RoundRectangle2D.Float(bx, by, fill, 6, 6, 6));
		g.setColor(Theme.STROKE_SOFT);
		g.draw(track);

		g.setColor(Theme.TEXT_FAINT);
		g.drawString(Ui.clip("Dust is called at " + needed + " days.", small, bw), bx, h - 9);
		g.dispose();
	}
}

package com.codex.steward.ui;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

/** Coins, changes, durations and dates in the short forms the panel uses. */
public final class Format
{
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("EEEE d MMMM yyyy", Locale.ENGLISH);
	private static final DateTimeFormatter SHORT = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter MONTH = DateTimeFormatter.ofPattern("MMM yy", Locale.ENGLISH);

	private Format()
	{
	}

	/** "8,240", "41.2k", "412k", "1.24M". */
	public static String amount(long n)
	{
		if (n < 10_000)
		{
			return String.format(Locale.ENGLISH, "%,d", n);
		}
		if (n < 100_000)
		{
			return trim(n / 1_000.0, 1) + "k";
		}
		if (n < 1_000_000)
		{
			return Math.round(n / 1_000.0) + "k";
		}
		if (n < 10_000_000)
		{
			return trim(n / 1_000_000.0, 2) + "M";
		}
		if (n < 1_000_000_000)
		{
			return trim(n / 1_000_000.0, 1) + "M";
		}
		return trim(n / 1_000_000_000.0, 2) + "B";
	}

	/** Coins in the short form, negative amounts with a minus: "812.4M", "-45.2k". */
	public static String coins(long gp)
	{
		return gp < 0 ? "-" + amount(-gp) : amount(gp);
	}

	/** A change with its sign: "+3.2M", "-412k", "0". */
	public static String signed(long gp)
	{
		return gp > 0 ? "+" + amount(gp) : gp < 0 ? "-" + amount(-gp) : "0";
	}

	/** A quantity change with its sign, written in full: "+1,240", "-6". */
	public static String count(long n)
	{
		return (n > 0 ? "+" : n < 0 ? "-" : "") + String.format(Locale.ENGLISH, "%,d", Math.abs(n));
	}

	/** A share as a whole percent, or "<1%". */
	public static String percent(double share)
	{
		if (share > 0 && share < 0.01)
		{
			return "<1%";
		}
		return Math.round(share * 100) + "%";
	}

	/** "just now", "12m ago", "3h ago", "2d ago". */
	public static String ago(long ms)
	{
		long minutes = Math.max(0, ms) / 60_000;
		if (minutes < 1)
		{
			return "just now";
		}
		if (minutes < 60)
		{
			return minutes + "m ago";
		}
		if (minutes < 48 * 60)
		{
			return minutes / 60 + "h ago";
		}
		return minutes / (24 * 60) + "d ago";
	}

	private static String trim(double value, int places)
	{
		String text = String.format(Locale.ENGLISH, "%." + places + "f", value);
		while (text.contains(".") && (text.endsWith("0") || text.endsWith(".")))
		{
			text = text.substring(0, text.length() - 1);
		}
		return text;
	}

	/** "2h 14m", "38m", "under a minute". */
	public static String duration(long ms)
	{
		long minutes = ms / 60_000;
		if (minutes < 1)
		{
			return "under a minute";
		}
		if (minutes < 60)
		{
			return minutes + "m";
		}
		return minutes / 60 + "h " + minutes % 60 + "m";
	}

	/** "14:02" in the player's own time. */
	public static String time(long epochMs)
	{
		return CLOCK.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Thu 16 Oct". */
	public static String day(long epochMs)
	{
		return DAY.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "16 Oct". */
	public static String shortDay(long epochMs)
	{
		return SHORT.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Oct 26". */
	public static String month(long epochMs)
	{
		return MONTH.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Thu 16 Oct" for a day book date. */
	public static String day(java.time.LocalDate date)
	{
		return DAY.format(date);
	}

	/** "Thursday 16 October 2026". */
	public static String date(long epochMs)
	{
		return DATE.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** An item stack the way the game writes it: "950", "45K", "12M". */
	public static String stack(long n)
	{
		if (n < 100_000)
		{
			return String.valueOf(n);
		}
		if (n < 10_000_000)
		{
			return n / 1_000 + "K";
		}
		return n / 1_000_000 + "M";
	}

	/** The colour the game writes a stack of that size in. */
	public static java.awt.Color stackColor(long n)
	{
		return n < 100_000 ? Theme.QTY_YELLOW : n < 10_000_000 ? Theme.QTY_WHITE : Theme.QTY_GREEN;
	}

	/** A count in full with separators: "12,400". */
	public static String quantity(long n)
	{
		return String.format(Locale.ENGLISH, "%,d", n);
	}

	/** "today", "1 day", "134 days". */
	public static String days(long n)
	{
		return n <= 0 ? "today" : n == 1 ? "1 day" : n + " days";
	}
}

