package com.codex.steward.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(getFont());
		paint(g, text, trailing, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a heading in a box; the card uses the same drawing. The font must already be set. */
	static void paint(Graphics2D g, String text, String trailing, int x, int y, int w, int h)
	{
		int mid = y + h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x + 4, mid - 4);
		diamond.lineTo(x + 8, mid);
		diamond.lineTo(x + 4, mid + 4);
		diamond.lineTo(x, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		FontMetrics fm = g.getFontMetrics();
		int textX = x + 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = x + w;
		if (trailing != null && !trailing.isEmpty())
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = x + w - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, x + w - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
	}
}

package com.codex.steward.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Tabs drawn as one engraved strip: the chosen segment is lit from below by a
 * gold glow, the rest sit quietly in the ink.
 */
public class Segmented extends JComponent
{
	private final String[] labels;
	private final boolean large;
	private final Animator slide = new Animator(this);
	private int selected;
	private int hover = -1;
	private IntConsumer listener;

	public Segmented(boolean large, String... labels)
	{
		this.labels = labels;
		this.large = large;
		setFont(large ? Theme.title() : Theme.small());
		int h = large ? 28 : 22;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				setSelected(indexAt(e.getX()), true);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	public void onChange(IntConsumer listener)
	{
		this.listener = listener;
	}

	public int getSelected()
	{
		return selected;
	}

	public void setSelected(int index, boolean notify)
	{
		if (index < 0 || index >= labels.length)
		{
			return;
		}
		boolean changed = index != selected;
		selected = index;
		slide.set(index, true);
		repaint();
		if (changed && notify && listener != null)
		{
			listener.accept(index);
		}
	}

	private int indexAt(int x)
	{
		int w = Math.max(1, getWidth());
		return Math.max(0, Math.min(labels.length - 1, x * labels.length / w));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float seg = w / (float) labels.length;

		RoundRectangle2D strip = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(strip);

		float x = (float) (slide.get() * seg);
		RoundRectangle2D lit = new RoundRectangle2D.Float(x + 2, 2, seg - 4, h - 4, 6, 6);
		g.setPaint(new GradientPaint(0, 2, Theme.CARD_TOP, 0, h, Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35)));
		g.fill(lit);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(lit);
		g.setColor(Theme.GOLD_BRIGHT);
		g.fillRect(Math.round(x + seg * 0.3f), h - 4, Math.round(seg * 0.4f), 1);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < labels.length; i++)
		{
			int tx = Math.round(i * seg + (seg - fm.stringWidth(labels[i])) / 2);
			int ty = (h + fm.getAscent()) / 2 - (large ? 2 : 1);
			java.awt.Color color = i == selected ? Theme.GOLD_BRIGHT : i == hover ? Theme.TEXT : Theme.TEXT_MUTED;
			Ui.shadowed(g, labels[i], tx, ty, color);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(strip);
		g.dispose();
	}
}

package com.codex.steward.ui;

import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.AffineTransform;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

/** The Steward's mark: a gilt bank key laid on the slant, with a teal stone set in its bow. */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;

		// The key is drawn upright on a 16 unit grid, then turned to lie on the slant.
		Area key = new Area(new Ellipse2D.Float(4.6f, 0.4f, 6.8f, 6.8f));
		key.subtract(new Area(new Ellipse2D.Float(6.3f, 2.1f, 3.4f, 3.4f)));
		key.add(new Area(new RoundRectangle2D.Float(7.1f, 6.4f, 1.8f, 9.2f, 1f, 1f)));
		key.add(new Area(new Rectangle2D.Float(8.6f, 11.6f, 2.6f, 1.4f)));
		key.add(new Area(new Rectangle2D.Float(8.6f, 13.9f, 2f, 1.5f)));
		key.add(new Area(new Rectangle2D.Float(6.2f, 7.4f, 3.6f, 0.9f)));

		AffineTransform at = new AffineTransform();
		at.translate(x, y);
		at.scale(s, s);
		at.rotate(Math.toRadians(-38), 8, 8);
		at.translate(0, 0.2);
		Area shape = key.createTransformedArea(at);

		g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
		g.setStroke(new BasicStroke(Math.max(1.2f, 1.4f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.draw(shape);
		g.setPaint(new GradientPaint(x, y, Theme.GOLD_BRIGHT, x + size, y + size, Theme.GOLD_DIM));
		g.fill(shape);
		g.setStroke(new BasicStroke(Math.max(0.5f, 0.45f * s)));
		g.setColor(Theme.alpha(Theme.INK_DEEP, 160));
		g.draw(shape);

		// The stone in the bow.
		float[] centre = {8f, 3.8f};
		at.transform(centre, 0, centre, 0, 1);
		float r = 1.45f * s;
		g.setColor(Theme.alpha(Theme.TEAL, 90));
		g.fill(new Ellipse2D.Float(centre[0] - r * 1.6f, centre[1] - r * 1.6f, r * 3.2f, r * 3.2f));
		g.setColor(Theme.mix(Theme.TEAL, Theme.TEXT, 0.35));
		g.fill(new Ellipse2D.Float(centre[0] - r, centre[1] - r, r * 2, r * 2));
	}
}

package com.codex.steward.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.steward.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tablet: a big number, its label, and a quiet line of context. */
class StatTile extends JComponent
{
	private final String value;
	private final String label;
	private final String note;
	private final Color color;

	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null || note.isEmpty() ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, value, label, note, color, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a tablet in a box; the card uses the same drawing. */
	static void paint(Graphics2D g, String value, String label, String note, Color color, int x, int y, int w, int h)
	{
		RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(x, y, Theme.CARD_TOP, x, y + h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(x + Theme.RADIUS, y + 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(), x + 8, y + 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(value, bold, w - 16), x + 8, y + 8 + small.getHeight() + bold.getAscent(), color);
		if (note != null && !note.isEmpty())
		{
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, w - 16), x + 8, y + h - 6);
		}
	}
}

package com.codex.steward.ui;

import com.codex.steward.core.Advice;
import com.codex.steward.core.Reckoning;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/**
 * The Steward's side panel: the crest, then three pages. Clear out lists what can go, Needed
 * lists what unfinished quests and diaries still hold back, and Kept lists what the player chose
 * to keep off the list.
 */
public class StewardPanel extends PluginPanel
{
	static final int WIDTH = 200;
	private static final String[] TABS = {"clear", "needed", "kept"};
	private static final int ROWS = 60;

	/** What the panel has to show. */
	public enum State
	{
		LOGGED_OUT,
		WAITING_FOR_BANK,
		READY
	}

	/** What the panel asks of the plugin. */
	public interface Actions
	{
		void keep(int itemId, boolean kept);
	}

	private final ItemIcons icons;
	private final Actions actions;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(true, "Clear out", "Needed", "Kept");
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane clear = scroller();
	private final JScrollPane needed = scroller();
	private final JScrollPane kept = scroller();

	private Reckoning reckoning;
	private Map<Integer, String> names = Collections.emptyMap();
	private State state = State.LOGGED_OUT;

	public StewardPanel(ItemIcons icons, Actions actions)
	{
		super(false);
		this.icons = icons;
		this.actions = actions;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		content.setOpaque(false);
		content.add(clear, TABS[0]);
		content.add(needed, TABS[1]);
		content.add(kept, TABS[2]);
		add(content, BorderLayout.CENTER);
		tabs.onChange(this::showTab);
		rebuild();
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return scroll;
	}

	/**
	 * Called on the Swing thread whenever the reckoning changes.
	 *
	 * @param reckoning the latest reckoning, or null when no bank is known
	 * @param names item names for every item the reckoning mentions
	 */
	public void update(Reckoning reckoning, Map<Integer, String> names, String player, State state)
	{
		this.reckoning = reckoning;
		this.names = names;
		this.state = state;
		updateCrest(player);
		rebuild();
	}

	/** Opens one tab, for previews and tests. */
	public void showTab(int index)
	{
		tabs.setSelected(index, false);
		cards.show(content, TABS[index]);
	}

	private void updateCrest(String player)
	{
		if (reckoning == null)
		{
			crest.update(player, null, state == State.LOGGED_OUT ? "Log in to take stock" : "Open your bank to take stock", null);
			return;
		}
		String status = state == State.LOGGED_OUT ? "Logged out, bank as last seen" : null;
		int[] counts = {reckoning.freedSlots(), reckoning.getSpent().size(), reckoning.getDust().size()};
		crest.update(player, reckoning.freedValue(), status, counts);
	}

	private void rebuild()
	{
		rebuildClear();
		rebuildNeeded();
		rebuildKept();
	}

	private boolean waiting(StackPanel stack)
	{
		if (reckoning != null)
		{
			return false;
		}
		if (state == State.LOGGED_OUT)
		{
			stack.add(note("The Steward is waiting", "Log in and Codex Bank Steward goes through your bank: what you can sell or drop because its quests and diaries are done, and what has sat untouched for months."));
		}
		else
		{
			stack.add(note("Open your bank once", "The Steward takes stock the first time it sees your bank. After that it remembers the bank as last seen and notices what you use."));
		}
		return true;
	}

	private void rebuildClear()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (waiting(stack))
		{
			replace(clear, stack);
			return;
		}
		List<Advice> spent = reckoning.getSpent();
		List<Advice> dust = reckoning.getDust();

		JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 6));
		tiles.setOpaque(false);
		tiles.add(new StatTile(Format.coins(value(spent)), "Done with", count(spent.size()), Theme.SPENT));
		tiles.add(new StatTile(Format.coins(value(dust)), "Dusty", count(dust.size()), Theme.DUST));
		stack.add(tiles);

		stack.add(new SectionHeader("Their work is done", spent.isEmpty() ? null : Format.coins(value(spent))));
		if (spent.isEmpty())
		{
			stack.add(note("Nothing spent yet", "Items bought or kept for a quest or diary land here once every quest and diary that needs them is done."));
		}
		else
		{
			stack.add(rows(spent, true));
			more(stack, spent);
		}

		stack.add(new SectionHeader("Gathering dust", dust.isEmpty() ? null : Format.coins(value(dust))));
		if (reckoning.getWatchedDays() < reckoning.getDustDays())
		{
			stack.add(new DustWatch(reckoning.getWatchedDays(), reckoning.getDustDays()));
		}
		else if (dust.isEmpty())
		{
			stack.add(note("No dust", "Everything in your bank has moved in the last " + reckoning.getDustDays() + " days."));
		}
		else
		{
			stack.add(rows(dust, true));
			more(stack, dust);
		}
		stack.add(Ui.wrapped("Click an item to keep it off the list. Nothing is ever sold or dropped for you.", Theme.small(), Theme.TEXT_FAINT, WIDTH - 20));
		replace(clear, stack);
	}

	private void rebuildNeeded()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (waiting(stack))
		{
			replace(needed, stack);
			return;
		}
		Map<String, List<Advice>> byTask = reckoning.getNeeded();
		Card head = new Card(new BorderLayout(0, 4));
		head.highlighted(true);
		head.add(Ui.label(reckoning.getTasksDone() + " of " + reckoning.getTasksTotal() + " done", Theme.title(), Theme.GOLD_BRIGHT), BorderLayout.NORTH);
		head.add(Ui.wrapped(byTask.isEmpty()
			? "Nothing in your bank is waiting on an unfinished quest or diary."
			: byTask.size() + " unfinished quests and diaries hold items back. Keep these until they are done.",
			Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		stack.add(head);
		for (Map.Entry<String, List<Advice>> e : byTask.entrySet())
		{
			long held = value(e.getValue());
			stack.add(new SectionHeader(e.getKey(), held > 0 ? Format.coins(held) : null));
			stack.add(rows(e.getValue(), false));
		}
		replace(needed, stack);
	}

	private void rebuildKept()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (waiting(stack))
		{
			replace(kept, stack);
			return;
		}
		List<Advice> list = reckoning.getKept();
		if (list.isEmpty())
		{
			stack.add(note("Nothing kept aside", "Click anything on the Clear out page to keep it. Kept items stay off the list until you let them go."));
		}
		else
		{
			stack.add(new SectionHeader("Kept aside", count(list.size())));
			stack.add(rows(list, true));
		}
		replace(kept, stack);
	}

	private JPanel rows(List<Advice> list, boolean withAction)
	{
		JPanel rows = new JPanel(new GridLayout(0, 1, 0, 1));
		rows.setOpaque(false);
		for (int i = 0; i < list.size() && i < ROWS; i++)
		{
			Advice a = list.get(i);
			String action = null;
			Runnable run = null;
			if (withAction && actions != null)
			{
				boolean isKept = a.getVerdict() == Advice.Verdict.KEPT;
				action = isKept ? "Let it go" : "Keep it";
				run = () -> actions.keep(a.getItemId(), !isKept);
			}
			rows.add(new AdviceRow(a, name(a.getItemId()), note(a), icons, action, run));
		}
		return rows;
	}

	private void more(StackPanel stack, List<Advice> list)
	{
		if (list.size() > ROWS)
		{
			stack.add(Ui.label("and " + (list.size() - ROWS) + " more, worth " + Format.coins(value(list.subList(ROWS, list.size()))),
				Theme.small(), Theme.TEXT_FAINT));
		}
	}

	/** The Steward's reason, in a few words. */
	private String note(Advice a)
	{
		switch (a.getVerdict())
		{
			case SPENT:
			{
				List<String> tasks = a.getTasks();
				String first = tasks.isEmpty() ? "Its quests" : tasks.get(0);
				return tasks.size() > 1 ? first + " +" + (tasks.size() - 1) + " done" : first + " done";
			}
			case DUST:
				return "Untouched " + Format.days(a.getUntouchedDays());
			case NEEDED:
				return a.getTasks().size() > 1 ? "Also for " + (a.getTasks().size() - 1) + " more" : a.isTradeable() ? Format.coins(a.getPrice()) + " each" : "Untradeable";
			default:
				return a.getUntouchedDays() > 0 ? "Kept, untouched " + Format.days(a.getUntouchedDays()) : "Kept";
		}
	}

	private String name(int itemId)
	{
		String name = names.get(itemId);
		return name == null ? "Item " + itemId : name;
	}

	private static long value(List<Advice> list)
	{
		long total = 0;
		for (Advice a : list)
		{
			total += a.getValue();
		}
		return total;
	}

	private static String count(int n)
	{
		return n == 1 ? "1 item" : n + " items";
	}

	static Card note(String title, String text)
	{
		Card card = new Card(new BorderLayout(0, 4));
		card.accent(Theme.GOLD_DIM);
		card.add(Ui.label(title, Theme.body(), Theme.GOLD), BorderLayout.NORTH);
		card.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		return card;
	}

	private static void replace(JScrollPane scroll, JComponent view)
	{
		int position = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(view);
		scroll.revalidate();
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}
}

package com.codex.steward.ui;

import com.codex.steward.core.Advice;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * The Steward marks what is done with in gold, what has gathered dust in ash, what is still
 * owed to unfinished work in the arcane teal and what the player chose to keep in violet, so an
 * item's colour says its verdict before its note is read.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** Item quantities in the game's own colours: yellow, white from 100K, green from 10M. */
	public static final Color QTY_YELLOW = new Color(255, 255, 0);
	public static final Color QTY_WHITE = new Color(255, 255, 255);
	public static final Color QTY_GREEN = new Color(0, 255, 128);

	public static final Color ASH = new Color(176, 156, 128);
	public static final Color SPENT = GOLD;
	public static final Color DUST = ASH;
	public static final Color NEEDED = TEAL;
	public static final Color KEPT = VIOLET;

	public static Color verdict(Advice.Verdict verdict)
	{
		switch (verdict)
		{
			case SPENT:
				return SPENT;
			case DUST:
				return DUST;
			case NEEDED:
				return NEEDED;
			default:
				return KEPT;
		}
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.steward.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}

	/** Text with the one pixel black shadow the game puts under its own lettering. */
	public static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	/** Cuts text to fit a width, ending it with an ellipsis. */
	public static String clip(String text, java.awt.FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + "...") > width)
		{
			end--;
		}
		return text.substring(0, end) + "...";
	}
}

package com.codex.steward.core;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import net.runelite.api.Quest;
import org.junit.Test;

public class CatalogTest
{
	private static Catalog load() throws Exception
	{
		try (Reader reader = new InputStreamReader(CatalogTest.class.getResourceAsStream("/com/codex/steward/steward-data.json"), StandardCharsets.UTF_8))
		{
			return new Catalog(new Gson().fromJson(reader, Catalog.Data.class));
		}
	}

	@Test
	public void bundledDataLoadsAndEveryQuestResolves() throws Exception
	{
		Catalog catalog = load();
		assertTrue(catalog.getTasks().size() > 200);
		assertTrue(catalog.getNeeds().size() > 1000);
		for (Task task : catalog.getTasks())
		{
			if (task.isDiary())
			{
				assertTrue(task.getName(), task.getVarbit() > 0 && task.getValue() > 0);
			}
			else
			{
				assertNotNull(task.getName(), Quest.valueOf(task.getQuest()));
			}
		}
	}

	@Test
	public void staplesAndLastingRewardsAreGuarded() throws Exception
	{
		Catalog catalog = load();
		assertTrue(catalog.isGeneral(995));
		assertTrue(catalog.isGeneral(561));
		assertTrue(catalog.isLasting(552));
		assertTrue(catalog.isLasting(4251));
		assertFalse(catalog.isGeneral(38));
		assertFalse(catalog.needsOf(38).isEmpty());
	}
}

package com.codex.steward.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class MemoryTest
{
	@Test
	public void firstLookIsTheBaselineAndLaterChangesAreMoves()
	{
		Memory memory = new Memory();
		Map<Integer, Long> bank = new HashMap<>();
		bank.put(1, 5L);
		bank.put(2, 1L);
		assertTrue(memory.observeBank(bank, 10));
		assertEquals(-1, memory.lastMoved(1));
		assertEquals(4, memory.untouchedDays(1, 14));

		Map<Integer, Long> next = new HashMap<>(bank);
		next.put(1, 4L);
		next.remove(2);
		next.put(3, 1L);
		assertTrue(memory.observeBank(next, 12));
		assertEquals(12, memory.lastMoved(1));
		assertEquals(12, memory.lastMoved(2));
		assertEquals(12, memory.lastMoved(3));
		assertFalse(memory.observeBank(next, 12));

		memory.observeHeld(Collections.singletonList(7), 13);
		assertEquals(13, memory.lastMoved(7));
	}
}

package com.codex.steward.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class ReckoningTest
{
	private static final int BAT_BONES = 530;
	private static final int GHOSTSPEAK = 552;
	private static final int PICK_RUNE = 1275;
	private static final int PICK_ADDY = 1271;
	private static final int NATURE = 561;
	private static final int OLD_BOOT = 9999;

	private static Catalog catalog()
	{
		Catalog.Data data = new Catalog.Data();
		data.tasks = Arrays.asList(
			new Task("Merlin's Crystal", Task.QUEST, "MERLINS_CRYSTAL", 0, 0),
			new Task("Watchtower", Task.QUEST, "WATCHTOWER", 0, 0),
			new Task("The Restless Ghost", Task.QUEST, "THE_RESTLESS_GHOST", 0, 0),
			new Task("Mining Thing", Task.QUEST, "X", 0, 0));
		data.needs = Arrays.asList(
			new int[]{0, 1, BAT_BONES},
			new int[]{1, 1, BAT_BONES},
			new int[]{2, 1, GHOSTSPEAK},
			new int[]{3, 1, PICK_RUNE, PICK_ADDY},
			new int[]{3, 5, NATURE});
		data.general = new int[]{NATURE};
		data.lasting = new int[]{GHOSTSPEAK};
		return new Catalog(data);
	}

	private static final Reckoning.Rules RULES = new Reckoning.Rules(90, 14);

	private static Reckoning reckon(Memory memory, Map<Integer, Long> bank, Set<Integer> held, boolean[] done, long today)
	{
		return Reckoning.of(catalog(), memory, bank, held, done, id -> 100, id -> id != GHOSTSPEAK, RULES, today);
	}

	private static Map<Integer, Long> bank(int... pairs)
	{
		Map<Integer, Long> map = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			map.put(pairs[i], (long) pairs[i + 1]);
		}
		return map;
	}

	@Test
	public void spentOnlyWhenEveryTaskIsDone()
	{
		Memory memory = new Memory();
		Map<Integer, Long> bank = bank(BAT_BONES, 3);
		memory.observeBank(bank, 100);

		Reckoning half = reckon(memory, bank, Collections.emptySet(), new boolean[]{true, false, false, false}, 100);
		assertTrue(half.getSpent().isEmpty());
		assertEquals(Collections.singletonList("Watchtower"), half.getNeeded().get("Watchtower").get(0).getTasks());

		Reckoning all = reckon(memory, bank, Collections.emptySet(), new boolean[]{true, true, false, false}, 100);
		assertEquals(1, all.getSpent().size());
		assertEquals(300, all.freedValue());
		assertEquals(Arrays.asList("Merlin's Crystal", "Watchtower"), all.getSpent().get(0).getTasks());
	}

	@Test
	public void aStackFarBeyondTheQuestsIsNotLeftovers()
	{
		Memory memory = new Memory();
		Map<Integer, Long> bank = bank(BAT_BONES, 900);
		memory.observeBank(bank, 100);
		Reckoning r = reckon(memory, bank, Collections.emptySet(), new boolean[]{true, true, false, false}, 100);
		assertTrue(r.getSpent().isEmpty());
	}

	@Test
	public void lastingAndGeneralItemsAreNeverSpent()
	{
		Memory memory = new Memory();
		Map<Integer, Long> bank = bank(GHOSTSPEAK, 1, NATURE, 500);
		memory.observeBank(bank, 100);
		Reckoning r = reckon(memory, bank, Collections.emptySet(), new boolean[]{true, true, true, true}, 100);
		assertTrue(r.getSpent().isEmpty());
	}

	@Test
	public void anyOfNeedHoldsOnlyTheBestOwnedChoice()
	{
		Memory memory = new Memory();
		Map<Integer, Long> bank = bank(PICK_RUNE, 1, PICK_ADDY, 1);
		memory.observeBank(bank, 100);
		Reckoning r = reckon(memory, bank, Collections.emptySet(), new boolean[4], 100);
		assertEquals(1, r.getNeeded().get("Mining Thing").size());
		assertEquals(PICK_RUNE, r.getNeeded().get("Mining Thing").get(0).getItemId());

		// Carrying the rune pickaxe meets the need, so the bank's spare is not held back by it.
		Reckoning carrying = reckon(memory, bank(PICK_ADDY, 1), new HashSet<>(Collections.singletonList(PICK_RUNE)), new boolean[4], 100);
		assertTrue(carrying.getNeeded().isEmpty());
	}

	@Test
	public void dustNeedsLongEnoughWatching()
	{
		Memory memory = new Memory();
		Map<Integer, Long> bank = bank(OLD_BOOT, 1, BAT_BONES, 2);
		memory.observeBank(bank, 100);
		assertTrue(reckon(memory, bank, Collections.emptySet(), new boolean[4], 150).getDust().isEmpty());

		memory.observeBank(bank(OLD_BOOT, 1, BAT_BONES, 1), 180);
		Reckoning later = reckon(memory, bank(OLD_BOOT, 1, BAT_BONES, 1), Collections.emptySet(), new boolean[4], 195);
		assertEquals(1, later.getDust().size());
		assertEquals(OLD_BOOT, later.getDust().get(0).getItemId());
		assertEquals(95, later.getDust().get(0).getUntouchedDays());
	}

	@Test
	public void recentlyUsedItemsAreNotSpentAndKeptItemsStayKept()
	{
		Memory memory = new Memory();
		memory.observeBank(bank(BAT_BONES, 3), 100);
		memory.observeBank(bank(BAT_BONES, 2), 110);
		boolean[] done = {true, true, false, false};
		assertTrue(reckon(memory, bank(BAT_BONES, 2), Collections.emptySet(), done, 115).getSpent().isEmpty());
		assertEquals(1, reckon(memory, bank(BAT_BONES, 2), Collections.emptySet(), done, 124).getSpent().size());

		memory.setKept(BAT_BONES, true);
		Reckoning r = reckon(memory, bank(BAT_BONES, 2), Collections.emptySet(), done, 124);
		assertTrue(r.getSpent().isEmpty());
		assertEquals(1, r.getKept().size());
	}
}

import com.questhelper.questhelpers.QuestDetails;
import com.questhelper.questinfo.QuestHelperQuest;
import com.questhelper.questhelpers.QuestHelper;
import com.questhelper.requirements.item.ItemRequirement;
import com.questhelper.requirements.item.ItemRequirements;
import com.questhelper.requirements.util.LogicType;
import com.google.gson.*;
import java.lang.reflect.Field;
import java.util.*;
import net.runelite.api.Quest;

public class ExtractQuestHelper {
  static Object field(Object o, String name) throws Exception {
    Field f = o.getClass().getDeclaredField(name); f.setAccessible(true); return f.get(o);
  }
  static void flatten(ItemRequirement r, List<JsonObject> out, List<String> notes) {
    if (r instanceof ItemRequirements) {
      ItemRequirements rs = (ItemRequirements) r;
      if (rs.getLogicType() == LogicType.OR) {
        // one of the children: merge every id into a single group
        Set<Integer> ids = new LinkedHashSet<>(); int qty = 1;
        for (ItemRequirement c : rs.getItemRequirements()) { ids.addAll(c.getAllIds()); qty = Math.max(qty, c.getQuantity()); }
        add(rs.getName(), new ArrayList<>(ids), qty, false, out);
      } else {
        for (ItemRequirement c : rs.getItemRequirements()) flatten(c, out, notes);
      }
      return;
    }
    add(r.getName(), r.getAllIds(), r.getQuantity(), false, out);
  }
  static void add(String name, List<Integer> ids, int qty, boolean kept, List<JsonObject> out) {
    List<Integer> real = new ArrayList<>();
    for (Integer id : ids) if (id != null && id > 0 && !real.contains(id)) real.add(id);
    if (real.isEmpty()) return;
    JsonObject o = new JsonObject(); o.addProperty("name", name);
    JsonArray a = new JsonArray(); real.forEach(a::add); o.add("ids", a); o.addProperty("qty", Math.max(1, qty));
    out.add(o);
  }
  static void inject(Object h) throws Exception {
    for (Class<?> c = h.getClass(); c != null; c = c.getSuperclass()) {
      for (Field f : c.getDeclaredFields()) {
        if (java.lang.reflect.Modifier.isStatic(f.getModifiers()) || f.getType().isPrimitive() || f.getType() == String.class) continue;
        String n = f.getType().getName();
        if (n.equals("net.runelite.api.Client") || n.equals("com.questhelper.QuestHelperPlugin") || n.equals("net.runelite.client.config.ConfigManager") || n.equals("net.runelite.client.game.ItemManager")) {
          f.setAccessible(true); if (f.get(h) == null) f.set(h, org.mockito.Mockito.mock(f.getType(), org.mockito.Mockito.RETURNS_DEEP_STUBS));
        }
      }
    }
  }
  public static void main(String[] args) throws Exception {
    JsonArray tasks = new JsonArray();
    Map<String, Integer> fails = new TreeMap<>();
    for (QuestHelperQuest q : QuestHelperQuest.values()) {
      QuestDetails.Type t = q.getQuestType();
      String kind;
      switch (t) { case P2P: case F2P: kind = "quest"; break; case MINIQUEST: kind = "miniquest"; break; case ACHIEVEMENT_DIARY: kind = "diary"; break; default: continue; }
      JsonObject task = new JsonObject(); task.addProperty("name", q.getName()); task.addProperty("kind", kind);
      if (kind.equals("diary")) {
        Object vb = field(q, "varbit"); task.addProperty("varbit", (Integer) field(vb, "id")); task.addProperty("value", (Integer) field(q, "completeValue"));
      } else {
        Quest match = null; for (Quest x : Quest.values()) if (x.getId() == q.getId()) match = x;
        if (match == null) { fails.merge("noQuest:" + q.getName(), 1, Integer::sum); continue; }
        task.addProperty("quest", match.name());
      }
      List<JsonObject> needs = new ArrayList<>(); List<String> notes = new ArrayList<>();
      try {
        QuestHelper h = q.getQuestHelper(); inject(h); h.initializeRequirements();
        List<ItemRequirement> reqs = h.getItemRequirements();
        if (reqs != null) for (ItemRequirement r : reqs) if (r != null) flatten(r, needs, notes);
      } catch (Throwable e) { fails.merge(e.getClass().getSimpleName() + ":" + q.getName(), 1, Integer::sum); }
      JsonArray n = new JsonArray(); needs.forEach(n::add); task.add("needs", n);
      tasks.add(task);
    }
    System.err.println("failures: " + fails);
    System.out.println(new GsonBuilder().setPrettyPrinting().create().toJson(tasks));
  }
}
